import{_ as i,C as r,o as l,c as p,j as d,a as e,E as o,a5 as a}from"./chunks/framework.CINlqUGR.js";const q=JSON.parse('{"title":"弹出确认","description":"","frontmatter":{},"headers":[],"relativePath":"components/popconfirm.md","filePath":"components/popconfirm.md","lastUpdated":1787598366000}'),h={name:"components/popconfirm.md"},s={id:"弹出确认",tabindex:"-1"};function m(f,t,b,g,u,x){const n=r("Badge"),c=r("XhDemo");return l(),p("div",null,[d("h1",s,[t[0]||(t[0]=e("弹出确认 ",-1)),o(n,{type:"info",text:"popconfirm"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#弹出确认","aria-label":'Permalink to "弹出确认 <Badge type="info" text="popconfirm" />"'},"​",-1))]),t[3]||(t[3]=a('<p>贴着触发器的一句确认：比对话框轻，但仍拦住一次误操作。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>影响有限、可撤销的删除或清空，且触发器就在近处。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>后果严重不可逆：用<a href="./dialog">对话框</a>，并让用户读到完整说明。</li><li>操作可以撤销：干脆直接做，配一条带&quot;撤销&quot;的<a href="./toast">轻提示</a>——那比事前确认体验好。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>确认按钮支持异步：在途期间进 pending 并拦住关闭，失败保持打开。</li><li>位置、尺寸、语气三轴。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>点触发器就地问一句，确认与取消都收起浮层；展开时焦点先落在取消上</p>',10)),o(c,{src:"popconfirm/01-basic"}),t[4]||(t[4]=d("h3",{id:"放置位",tabindex:"-1"},[e("放置位 "),d("a",{class:"header-anchor",href:"#放置位","aria-label":'Permalink to "放置位"'},"​")],-1)),t[5]||(t[5]=d("p",null,"placement 是首选位，位置不够时引擎自己避让，实际落点写在 data-placement 上",-1)),o(c,{src:"popconfirm/02-placement"}),t[6]||(t[6]=d("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[7]||(t[7]=d("p",null,"size 换的是面板的内边距与最大宽度，三个档位落在 content 上",-1)),o(c,{src:"popconfirm/03-size"}),t[8]||(t[8]=d("h3",{id:"语气",tabindex:"-1"},[e("语气 "),d("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[9]||(t[9]=d("p",null,"在 content 上写 data-tone，确认按钮跟着换色；语气是共享的一层，不是本组件的 prop",-1)),o(c,{src:"popconfirm/04-tone"}),t[10]||(t[10]=d("h3",{id:"异步确认",tabindex:"-1"},[e("异步确认 "),d("a",{class:"header-anchor",href:"#异步确认","aria-label":'Permalink to "异步确认"'},"​")],-1)),t[11]||(t[11]=d("p",null,"确认回调返回 Promise 即挂起确认门：浮层等兑现才收起、确认按钮转圈且再点无效，落空（reject）留在原地；不必再手动受控拦收起",-1)),o(c,{src:"popconfirm/05-async-confirm"}),t[12]||(t[12]=a('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-popconfirm&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhPopconfirmCancelTrigger</code> <code>XhPopconfirmConfirmTrigger</code> <code>XhPopconfirmContent</code> <code>XhPopconfirmDescription</code> <code>XhPopconfirmPositioner</code> <code>XhPopconfirmRoot</code> <code>XhPopconfirmTitle</code> <code>XhPopconfirmTrigger</code></td></tr><tr><td>组合式函数</td><td><code>usePopconfirm</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/popconfirm.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;popconfirm&quot;</code>：<strong><code>root</code></strong> · <strong><code>trigger</code></strong> · <code>positioner</code> · <strong><code>content</code></strong> · <code>title</code> · <code>description</code> · <strong><code>confirm-trigger</code></strong> · <strong><code>cancel-trigger</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>closeOnEscape</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>closeOnInteractOutside</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，缺省 ltr。只改写浮层在行内轴上 start 与 end 的落点。</td></tr><tr><td><code>offset</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>onCancel</code></td><td><code>() =&gt; void</code></td><td></td><td>点了取消按钮，随后浮层收起；挂起中的确认结果随之作废。Escape 与层外交互只发 onOpenChange，不发这条。</td></tr><tr><td><code>onConfirm</code></td><td><code>() =&gt; void | Promise&lt;unknown&gt;</code></td><td></td><td>点了确认按钮。返回 Promise 即挂起确认门：浮层等它兑现才收起、 确认按钮转圈且再点无效，落空（reject）则留在原地不收。同步返回照旧立即收起。</td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: PopoverOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图；受控时是唯一出口，非受控时随内部转移一并通知。</td></tr><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>placement</code></td><td><code>Placement</code></td><td></td><td></td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，决定面板的内边距档位。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>PopoverOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr><tr><td><code>confirm</code></td><td>``</td><td>点了确认按钮；随后浮层收起。异步门走 confirmAction 属性： 事件拿不到监听函数的返回值，给元素赋 <code>confirmAction = () =&amp;gt; Promise</code> 即挂起确认门 （浮层等兑现才收、确认按钮转圈，落空留在原地），confirm 事件照发只作通知</td></tr><tr><td><code>cancel</code></td><td>``</td><td>点了取消按钮；随后浮层收起</td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhPopconfirmRoot</code></td><td><code>default</code></td><td><code>PopconfirmRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>usePopconfirm</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>pending</code></td><td><code>boolean</code></td><td>异步确认进行中：确认按钮转圈、再点无效。</td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>confirm</code></td><td><code>() =&gt; void</code></td><td>发确认意图并请求收起；异步确认挂起期间再调无效。</td></tr><tr><td><code>cancel</code></td><td><code>() =&gt; void</code></td><td>发取消意图并请求收起。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getPositionerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDescriptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getConfirmTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getCancelTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/alertdialog/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in trigger</td><td>切换开合，展开时把焦点移入 content</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in confirm-trigger</td><td>发确认意图并收起浮层</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in cancel-trigger</td><td>发取消意图并收起浮层</td></tr><tr><td><code>Escape</code></td><td>open</td><td>收起浮层并把焦点还给 trigger；不发确认也不发取消</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-haspopup</code></td><td>&#39;dialog&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-describedby</code></td><td><code>description</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>aria-labelledby</code></td><td><code>title</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;alertdialog&#39;</td></tr><tr><td><code>confirm-trigger</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/popconfirm.css</code> 按部件选择：<code>[data-scope=&quot;popconfirm&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-hidden</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>positioner</code></td><td><code>data-positioned</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>content</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>confirm-trigger</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-popconfirm-action-radius</code> · <code>--xh-popconfirm-bg</code> · <code>--xh-popconfirm-border</code> · <code>--xh-popconfirm-cancel-bg</code> · <code>--xh-popconfirm-cancel-fg</code> · <code>--xh-popconfirm-cancel-trigger-px</code> · <code>--xh-popconfirm-confirm-bg</code> · <code>--xh-popconfirm-confirm-fg</code> · <code>--xh-popconfirm-description-fg</code> · <code>--xh-popconfirm-fg</code> · <code>--xh-popconfirm-gap</code> · <code>--xh-popconfirm-layer</code> · <code>--xh-popconfirm-loading-duration</code> · <code>--xh-popconfirm-max-w</code> · <code>--xh-popconfirm-px</code> · <code>--xh-popconfirm-py</code> · <code>--xh-popconfirm-radius</code> · <code>--xh-popconfirm-shadow</code> · <code>--xh-popconfirm-title-fg</code> · <code>--xh-popconfirm-title-font-size</code> · <code>--xh-popconfirm-title-font-weight</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-pop-in</code> · <code>xh-pop-out</code> · <code>xh-popconfirm-rotate</code> 随皮肤自带，不引用别处文件里的名字；状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>触发器用<a href="./button">按钮</a>；放进<a href="./table">表格</a>的行操作、<a href="./menu">菜单</a>的条目旁。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>标题直接问那件事（&quot;删除这条记录？&quot;），描述写清后果。</li><li>确认按钮写动作名，并对破坏性操作用危险语气。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>每一个操作都要确认：用户会条件反射地点确认，确认就失去意义了。</li><li>确认框里没说清楚要删的是哪一条。</li></ul>',44))])}const k=i(h,[["render",m]]);export{q as __pageData,k as default};
